{
  "schemaVersion": "0.2",
  "slug": "heading",
  "name": "Heading",
  "status": "experimental",
  "purpose": "Renders a semantic heading at a chosen level.",
  "scenarios": [
    "Page title",
    "Section heading",
    "Card heading"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Heading text."
    },
    "level": {
      "type": "enum",
      "required": false,
      "description": "Semantic heading level.",
      "values": [
        "level-1",
        "level-2",
        "level-3",
        "level-4",
        "level-5",
        "level-6"
      ],
      "default": "level-2"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "level",
      "values": [
        "level-1",
        "level-2",
        "level-3",
        "level-4",
        "level-5",
        "level-6"
      ],
      "default": "level-2",
      "description": "Semantic heading level."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Heading rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card",
      "dialog"
    ],
    "allowedChildren": [
      "text",
      "icon"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not skip heading levels for visual effect.",
    "Do not use heading styles on non-heading elements."
  ],
  "a11y": {
    "role": "heading",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Contents provide the heading text.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Size scales with viewport.",
    "breakpoints": {
      "compact": "Smaller font size.",
      "medium": "Medium size.",
      "large": "Large size."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "heading",
    "states": [
      "level-1",
      "level-2",
      "level-3",
      "level-4",
      "level-5",
      "level-6"
    ],
    "intents": [
      "structure-content"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export type HeadingLevel = 'level-1' | 'level-2' | 'level-3' | 'level-4' | 'level-5' | 'level-6'

export interface HeadingProps {
  children: ReactNode
  level?: HeadingLevel
  className?: string
}

const tagByLevel: Record<HeadingLevel, 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'> = {
  'level-1': 'h1',
  'level-2': 'h2',
  'level-3': 'h3',
  'level-4': 'h4',
  'level-5': 'h5',
  'level-6': 'h6',
}

export function Heading({ children, level = 'level-2', className }: HeadingProps) {
  const classes = ['cu-heading', 'cu-heading--' + level, className].filter(Boolean).join(' ')
  const Tag = tagByLevel[level]
  return <Tag className={classes} data-ai-role="heading" data-ai-intent="structure-content" data-ai-state={level}>{children}</Tag>
}

.cu-heading {
  margin: 0;
  color: var(--cu-color-fg-default);
  font-weight: 700;
  line-height: 1.2;
}

.cu-heading--level-1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
}

.cu-heading--level-2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
}

.cu-heading--level-3 {
  font-size: clamp(1.25rem, 2.5vw, 1.5rem);
}

.cu-heading--level-4 {
  font-size: 1.125rem;
}

.cu-heading--level-5 {
  font-size: 1rem;
}

.cu-heading--level-6 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
